import re,json,unicodedata
from pathlib import Path
bib=Path('<HOME>').read_text()
# basic entries
entries=[]
for m in re.finditer(r'@\\w+\\{(["'^,]+),'"',bib):
 st=m.start(); nxt=re.search(r'\\n@\\w+\\{',bib[m.end():]); en=(m.end()+nxt.start() if nxt else len(bib))
 chunk=bib[st:en]
 key=m.group(1)
 def fld(name):
  mm=re.search(r'\\b'+name+r'\\s*=\\s*\\{(["'^{}]*(?:'"\\{["'^{}]*'"\\}["'^{}]*)*)'"\\}',chunk,re.I|re.S)
  return mm.group(1).strip() if mm else ''
 entries.append((key,fld('doi').lower(),fld('title')))
rows=[json.loads(l) for l in open('<HOME>')]
bydoi={d:k for k,d,t in entries if d}
print('bib',len(entries),'with doi',sum(bool(d) for _,d,_ in entries),'papers doi',sum(bool(r.get('doi')) for r in rows))
matched=[]; unmatched=[]
for r in rows:
 d=(r.get('doi') or '').lower().strip()
 k=bydoi.get(d)
 if k: matched.append((k,r))
 else: unmatched.append(r)
print('matched doi',len(matched),'unmatched',len(unmatched))
print('unmatched sample:')
for r in unmatched[:40]: print(r.get('id'),r.get('doi'),r.get('title'))
print('bib no doi')
for k,d,t in entries:
 if not d: print(k,t)
